const lock = '<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="5" y="8" width="10" height="9" rx="2"/><path d="M7 8V5a3 3 0 016 0v3"/><path d="M10 11v3"/></svg>';
const sample = '<span class="sample-label">콘텐츠 예시</span>';
function imageCard(item){return `<button class="gallery-card" data-image="${item.id}" aria-label="${item.short} 크게 보기"><img src="assets/${item.file}" alt="${item.short} SEM 관찰 이미지" loading="lazy"><div class="gallery-caption"><div><span>${item.en}</span><h3>${item.short}</h3></div><b aria-hidden="true">+</b></div></button>`;}
function activityCard(item){return `<a class="activity-card" href="#/activities/${item.id}"><div class="card-image"><img src="assets/${item.image}" alt="${item.title} 관련 SEM 관찰 이미지" loading="lazy"><span class="image-label">${item.label}</span></div><div class="card-meta"><span class="category">${item.category}</span>${sample}</div><h3>${item.title}</h3><p>${item.description}</p></a>`;}
function values(){return `<div class="values-grid"><div class="value"><span class="value-number">01 /</span><span class="value-en">OBSERVE</span><h3>자세히 바라보고</h3><p>익숙한 생물 속 낯선 구조를 발견합니다. 작은 관찰에서 새로운 탐구가 시작됩니다.</p></div><div class="value"><span class="value-number">02 /</span><span class="value-en">CONNECT</span><h3>수업으로 연결하고</h3><p>현미경 앞에서 생긴 질문을 교실로 가져갑니다. 생생한 관찰이 배움의 깊이를 더합니다.</p></div><div class="value"><span class="value-number">03 /</span><span class="value-en">SHARE</span><h3>함께 나눕니다</h3><p>각자의 발견과 경험이 모여 모두의 자료가 됩니다. 동료 교사와 함께 성장합니다.</p></div></div>`;}
function joinBanner(){return `<section class="container join-banner"><div><div class="eyebrow">GROW TOGETHER</div><h2>다음 발견을, 함께 만들어 갈 선생님께.</h2><p>관찰의 즐거움을 나누고 생물교육의 가능성을 넓혀 갑니다.</p></div><button class="button lime" data-auth="join">BioSEM 함께하기</button></section>`;}
function home(){return `<section class="container hero"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">BIOLOGY TEACHERS’ SEM COMMUNITY</div><h1>작은 세계를 들여다보다.<br><em>더 넓은 배움</em>을 열다.</h1><p class="hero-description">주사전자현미경으로 발견하는 생명의 새로운 표정.<br>관찰의 순간을 기록하고, 함께 탐구하며,<br>교실 속 배움으로 이어가는 생물교사 공동체입니다.</p><div class="hero-buttons"><a class="button primary" href="#/gallery">SEM 갤러리 둘러보기</a><a class="button" href="#/about">BioSEM 알아보기</a></div><p class="hero-note">${lock}함께 탐구하는 교사를 위한 승인제 커뮤니티</p></div><div class="hero-image"><img src="assets/pollen.jpg" alt="꽃가루의 미세한 표면을 보여주는 주사전자현미경 사진" fetchpriority="high"><div class="image-top"><span>SEM ARCHIVE</span><span>01 — 03</span></div><div class="image-bottom"><div><small>A CLOSER LOOK AT LIFE</small><h2>보이지 않던 세계를 만나다.</h2></div><button class="image-circle" data-image="pollen" aria-label="대표 이미지 자세히 보기">+</button></div></div></div></section><div class="container notice-bar"><span class="notice-tag">NOTICE</span><a href="#/community/welcome" class="notice-title">BioSEM, 함께 관찰하고 배우는 공간을 엽니다.</a><time>시작 안내</time><a class="notice-more" href="#/community">더 보기</a></div><section class="container section"><div class="section-heading"><div><div class="eyebrow">OUR FIELD NOTES</div><h2>관찰에서 시작된 이야기</h2><p>현미경 앞에서, 그리고 교실에서 쌓아가는 기록.</p></div><a class="text-link" href="#/activities">활동 기록 전체 보기</a></div><div class="activity-grid">${activities.map(activityCard).join('')}</div></section><section class="section gallery-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">THE UNSEEN WORLD</div><h2>다르게 보면, 새롭게 보입니다.</h2><p>작은 구조에 담긴 생명의 질서를 만나보세요.</p></div><a class="text-link" href="#/gallery">갤러리 전체 보기</a></div><div class="gallery-grid">${images.map(imageCard).join('')}</div><p class="gallery-footnote">공개 라이선스 관찰 이미지로 구성한 갤러리입니다. 이미지별 출처는 상세 보기에서 확인할 수 있습니다.</p></div></section><section class="container section"><div class="section-heading"><div><div class="eyebrow">OUR PERSPECTIVE</div><h2>한 사람의 발견이, 모두의 배움으로.</h2></div><a class="text-link" href="#/about">우리의 방향</a></div>${values()}</section>${joinBanner()}`;}
function pageHead(page,eyebrow,description){return `<div class="container page-head"><div class="breadcrumb"><a href="#/">홈</a> &nbsp;/&nbsp; ${navLabels[page]}</div><div class="eyebrow">${eyebrow}</div><h1>${navLabels[page]}</h1><p>${description}</p></div>`;}
function about(){return `${pageHead('about','ABOUT BIOSEM','생명의 작은 구조를 탐구하고, 발견의 경험을 교실로 잇습니다.')}<div class="container page-body"><div class="editorial-block"><img src="assets/diatom.jpg" alt="규조류의 정교한 미세구조" loading="lazy"><div class="editorial-copy"><div class="eyebrow">OUR COMMUNITY</div><h2 style="margin-top:20px">함께 들여다볼 때,<br>더 많은 것이 보입니다.</h2><p>BioSEM은 생물교사들이 주사전자현미경(SEM)을 활용해 생명의 미세한 세계를 탐구하고, 그 경험을 교육으로 확장하기 위한 공동체입니다.</p><p>관찰 이미지를 공유하는 데서 한 걸음 더 나아가, 무엇을 발견했는지, 어떤 질문이 생겼는지, 수업에서 어떻게 함께 탐구할지 이야기합니다.</p><button class="button primary" data-auth="join">함께하는 방법</button></div></div><div class="feature-quote"><span>OUR BELIEF</span>관찰은 더 깊게.<br>질문은 더 넓게. 배움은 함께.</div><div class="section-heading"><div><div class="eyebrow">VISION & DIRECTION</div><h2>BioSEM이 나아갈 방향</h2></div></div>${values()}<div class="soft-panel" style="margin-top:45px"><h2>우리의 다음 장</h2><p>함께 만들어 갈 활동 방향입니다. 세부 일정은 확정 후 공지합니다.</p><div class="milestones"><div class="milestone"><strong>STEP 01 · 기반 만들기</strong><h3>관찰 경험 모으기</h3><p>구성원의 관심 분야와 관찰 주제를 모아 공동 탐구의 출발점을 찾습니다.</p></div><div class="milestone"><strong>STEP 02 · 함께 탐구하기</strong><h3>기록과 자료 축적하기</h3><p>관찰 과정과 이미지를 기록하고, 설명과 출처를 갖춘 자료를 쌓아갑니다.</p></div><div class="milestone"><strong>STEP 03 · 교실로 확장하기</strong><h3>수업 사례 나누기</h3><p>탐구 결과를 수업에 적용하고, 학생의 질문과 교사의 경험을 공유합니다.</p></div></div></div><p class="section-note">설립 연혁과 실제 활동 성과는 자료 확인 후 추가할 예정입니다.</p></div>${joinBanner()}`;}
function activitiesPage(){return `${pageHead('activities','FIELD NOTES','함께 관찰하고, 질문하고, 수업으로 연결하는 과정을 기록합니다.')}<section class="container page-body"><div class="filter-row"><div class="filter-tabs" data-filter-group="activities">${['전체','공동 탐구','연수 · 워크숍','수업 나눔'].map((x,i)=>`<button class="filter-tab ${i===0?'active':''}" data-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><span class="result-count" id="activity-count">3개의 예시 기록</span></div><div class="activity-grid" id="activity-results">${activities.map(activityCard).join('')}</div><p class="section-note">위 기록은 디자인과 콘텐츠 구성을 확인하기 위한 예시입니다. 실제 활동 내용으로 교체할 예정입니다.</p></section>`;}
function galleryPage(){return `${pageHead('gallery','SEM IMAGE ARCHIVE','확대할수록 새로워지는 생명의 표정. 이미지를 선택해 자세히 살펴보세요.')}<section class="container page-body"><div class="filter-row"><div class="filter-tabs" data-filter-group="gallery"><button class="filter-tab active" data-filter="all" aria-pressed="true">전체</button><button class="filter-tab" data-filter="plant" aria-pressed="false">식물</button><button class="filter-tab" data-filter="micro" aria-pressed="false">미생물</button></div><span class="result-count" id="gallery-count">${images.length}개의 관찰 이미지</span></div><div class="full-gallery" id="gallery-results">${images.map(imageCard).join('')}</div><p class="section-note">현재는 공개 라이선스 SEM 이미지로 구성되어 있습니다. 회원의 실제 관찰 이미지는 승인된 계정으로 등록할 수 있도록 연결할 예정입니다.</p></section>`;}
const resources = [
 {id:'intro',type:'입문 안내',icon:'GUIDE',title:'SEM 관찰을 시작하는 선생님께',summary:'관찰 전 알아두면 좋은 기록 원칙과 질문',content:'<h3>먼저, 관찰 질문을 정합니다</h3><p>무엇을 관찰할지와 어떤 차이를 비교할지를 먼저 정리하세요. 관찰 대상의 이름, 채집 장소와 날짜를 남기면 이후 기록을 다시 이해하는 데 도움이 됩니다.</p><h3>관찰 조건을 함께 기록합니다</h3><p>시료명, 준비 과정, 촬영 조건, 스케일바, 관찰한 내용을 이미지와 함께 남깁니다. 배율 숫자만으로 크기를 판단하기보다 원본에 포함된 스케일바를 확인하는 습관을 들여보세요.</p><h3>보이는 사실과 해석을 구분합니다</h3><p>형태, 배열, 무늬처럼 이미지에서 직접 확인할 수 있는 사실을 먼저 적고, 구조의 기능에 대한 해석은 별도로 정리하세요. 이미지 한 장으로 확인하기 어려운 내용은 추가 관찰 질문으로 남깁니다.</p><h3>장비별 절차를 확인합니다</h3><p>시료 준비와 장비 조작은 이용 기관의 안내와 담당자의 지도를 따릅니다. 구체적인 촬영 조건과 전처리 방법은 시료와 장비에 따라 달라집니다.</p>'},
 {id:'worksheet',type:'수업 활동지',icon:'NOTE',title:'관찰 → 질문 → 설명, 탐구 기록지',summary:'바로 인쇄해 사용할 수 있는 기본 관찰 활동지',content:'<p>관찰 이미지를 보며 아래 항목을 채워보세요.</p><h3>1. 관찰 대상과 조건</h3><p>이름: ____________________　날짜: ____________________<br>시료명: __________________　이미지 출처: __________________<br>스케일바 및 관찰 조건: ____________________________________</p><h3>2. 이미지에서 확인한 사실</h3><p>형태, 표면, 배열, 반복되는 무늬를 기록해 보세요.<br><br>________________________________________________________<br><br>________________________________________________________</p><h3>3. 새롭게 생긴 질문</h3><p>관찰하면서 궁금해진 점은 무엇인가요?<br><br>________________________________________________________<br><br>________________________________________________________</p><h3>4. 근거를 들어 설명하기</h3><p>어떤 관찰 내용이 내 설명을 뒷받침하나요?<br><br>________________________________________________________</p><h3>5. 다음 관찰 계획</h3><p>질문을 확인하려면 무엇을 더 관찰하거나 비교해야 할까요?<br><br>________________________________________________________</p>'},
 {id:'checklist',type:'기록 가이드',icon:'LIST',title:'함께 쓰는 SEM 이미지 기록 체크리스트',summary:'관찰 자료를 나누기 전에 확인할 항목',content:'<h3>자료를 공유하기 전에</h3><ul><li>시료의 이름과 관찰 부위를 적었나요?</li><li>촬영자, 촬영일, 이용 장비 정보를 확인했나요?</li><li>원본의 스케일바가 잘 보이나요?</li><li>이미지 크기를 바꾸면서 스케일바가 왜곡되지 않았나요?</li><li>전처리 과정과 주요 관찰 조건을 기록했나요?</li><li>보이는 사실과 추정한 설명을 구분했나요?</li><li>공유 권한과 출처 표기를 확인했나요?</li><li>학생 이름 등 불필요한 개인정보가 포함되지 않았나요?</li></ul><p>관찰 환경에 맞추어 항목을 보완해 활용하세요.</p>'}
];
function resourcesPage(){return `${pageHead('resources','TEACHING RESOURCES','관찰의 경험이 교실의 배움으로 이어지도록. 함께 쓰는 안내와 기록 도구입니다.')}<section class="container page-body"><div class="resource-list">${resources.map(r=>`<button class="resource-row" data-resource="${r.id}"><span class="resource-icon">${r.icon}</span><span class="resource-text"><h3>${r.title}</h3><p>${r.summary}</p></span><span class="resource-type">${r.type}</span><span aria-hidden="true">+</span></button>`).join('')}</div><div class="soft-panel" style="margin-top:35px"><h2>선생님의 수업 경험을 기다립니다.</h2><p>실제 수업에 적용한 활동지와 관찰 자료는 회원 인증 연결 후 승인된 회원끼리 나눌 예정입니다.</p><button class="button small" data-auth="join">참여 안내 보기</button></div></section>`;}
function process(){return `<div class="member-process"><div class="process-item"><strong>01 · APPLY</strong><h3>가입 신청</h3><p>이름과 소속, 관심 분야를 작성합니다.</p></div><div class="process-item"><strong>02 · REVIEW</strong><h3>운영진 확인</h3><p>교사 여부와 참여 정보를 운영진이 확인합니다.</p></div><div class="process-item"><strong>03 · CONNECT</strong><h3>승인 후 활동</h3><p>승인된 회원만 커뮤니티의 회원 활동에 참여합니다.</p></div></div>`;}
function membersPage(){return `${pageHead('members','PEOPLE OF BIOSEM','서로 다른 교실에서 출발해, 같은 호기심으로 만나는 사람들.')}<section class="container page-body"><div class="empty-state"><div class="empty-symbol" aria-hidden="true">◎</div><h2>함께할 선생님들의 자리를 마련했습니다.</h2><p>구성원 소개는 본인 확인과 공개 동의를 거쳐 등록합니다.<br>관심 분야와 탐구 주제로 서로를 알아갈 수 있는 공간입니다.</p><button class="button primary" data-auth="join">BioSEM 참여 안내</button></div><div class="section-heading" style="margin-top:45px"><div><div class="eyebrow">MEMBERSHIP</div><h2>신뢰할 수 있는 동료 공동체</h2><p>BioSEM은 운영진의 확인을 거친 회원과 함께합니다.</p></div></div>${process()}<p class="section-note">운영진과 협력 기관 정보는 확정 후 소개합니다.</p></section>`;}
const posts=[{id:'welcome',category:'공지사항',title:'BioSEM에 오신 것을 환영합니다.',body:'<p>BioSEM은 SEM 관찰을 바탕으로 생물교육의 새로운 가능성을 함께 탐구하는 교사 공동체입니다.</p><h3>이곳에서 함께할 일</h3><p>관찰 이미지를 보고 질문을 나누고, 활동 과정을 기록하고, 수업에서 활용할 방법을 찾아갑니다. 소개와 갤러리를 둘러보며 BioSEM의 방향을 확인해 주세요.</p><h3>회원 가입 안내</h3><p>회원 활동에는 본인 확인과 운영진 승인이 필요합니다. 로그인 화면에서 현재 이용 가능 여부를 확인해 주세요.</p>'},{id:'membership',category:'공지사항',title:'가입 및 회원 승인 절차를 안내합니다.',body:'<p>BioSEM은 교사들이 안심하고 자료와 경험을 나눌 수 있도록 승인제로 운영할 계획입니다.</p><h3>신청 → 확인 → 승인</h3><p>로그인 수단으로 본인을 확인한 뒤, 이름과 소속 등 참여 정보를 제출합니다. 운영진이 교사 여부와 신청 내용을 확인하고 승인하면 회원 활동을 이용할 수 있습니다.</p><p>구글·카카오 로그인만으로 회원 활동 권한이 부여되지 않습니다. 운영진의 별도 승인을 거쳐야 합니다.</p><p>가입 접수와 로그인 이용 가능 여부는 로그인 화면에서 안내합니다. 신청 상태는 내 계정에서 확인할 수 있습니다.</p>'}];
function communityPage(){return `${pageHead('community','COMMUNITY','혼자 품었던 질문을 나누면, 함께 탐구할 이야기가 됩니다.')}<section class="container page-body"><div class="filter-row"><div class="filter-tabs" data-filter-group="community">${['공지사항','자유 나눔','질문과 답변','활동 일정'].map((x,i)=>`<button class="filter-tab ${i===0?'active':''}" data-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><button class="button small primary" data-member-action="write">글쓰기</button></div><div id="community-results">${postList()}</div></section>`;}
function postList(){return posts.map(p=>`<a class="community-item" href="#/community/${p.id}"><span class="community-tag">안내</span><span class="post-title">${p.title}</span><span class="post-meta">BioSEM · 시작 안내</span></a>`).join('');}
function creditsPage(){return `${pageHead('credits','IMAGE CREDITS','관찰 이미지의 출처와 이용 조건을 안내합니다.')}<section class="container page-body source-list">${images.map(i=>`<div class="soft-panel"><h2>${i.short}</h2><p>${i.credit}</p><p><a href="${i.source}" target="_blank" rel="noopener noreferrer">원본 및 라이선스 보기</a></p></div>`).join('')}<p>레이아웃에 맞게 이미지를 자르고 흑백으로 표시했습니다. 관찰 조건과 배율은 확인되지 않은 값을 임의로 기재하지 않았습니다.</p></section>`;}
function openModal(html,cls=''){modal.dataset.revision=String(Number(modal.dataset.revision||0)+1);modal.className=cls;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();document.body.style.overflow='hidden';}
function closeModal(){modal.close();document.body.style.overflow='';}
function openImage(id){const i=images.find(x=>x.id===id);if(!i)return;openModal(`<img class="lightbox-image" src="assets/${i.file}" alt="${i.short} SEM 이미지"><div class="lightbox-body"><div class="eyebrow">${i.en}</div><h2 id="modal-title">${i.name}</h2><p>${i.description}</p><p class="image-credit">${i.credit}<br><a href="${i.source}" target="_blank" rel="noopener noreferrer">원본 이미지 및 이용 조건 확인</a></p></div>`,'gallery-modal');}
function openAuth(mode){if(window.BioSEMAuth){window.BioSEMAuth.open(mode);return;}openPreviewAuth(mode);}
function openPreviewAuth(mode){if(mode==='join'){openModal(`<div class="modal-inner"><div class="eyebrow">JOIN OUR COMMUNITY</div><h2 id="modal-title">함께 탐구할 준비가 되셨나요?</h2><p>BioSEM은 운영진의 확인을 거친 생물교사들이 함께하는 커뮤니티입니다.</p><div class="auth-message"><strong>가입 신청 → 운영진 확인 → 회원 승인</strong><br>구글·카카오 로그인 후에도 운영진 승인이 필요합니다.</div><p class="preview-note">현재는 디자인 미리보기입니다. 실제 가입 접수는 인증 서비스 연결 후 시작합니다.</p><button class="button primary wide" data-auth="form">가입 신청 화면 살펴보기</button><div class="auth-switch">이미 회원이신가요?<button data-auth="login">로그인</button></div></div>`);return;}if(mode==='form'){openModal(`<div class="modal-inner"><div class="eyebrow">MEMBERSHIP APPLICATION</div><h2 id="modal-title">BioSEM 가입 신청</h2><p>함께할 선생님에 대해 알려주세요.</p><div class="auth-message">디자인 확인용 화면입니다. 입력 정보는 전송하거나 저장하지 않습니다. 실제 개인정보 대신 예시를 입력해 주세요.</div><form id="join-form"><div class="form-grid"><label class="form-field">이름<input name="name" required maxlength="40" placeholder="이름 예시" autocomplete="off"></label><label class="form-field">소속 학교·기관<input name="school" required maxlength="100" placeholder="○○고등학교" autocomplete="off"></label></div><label class="form-field">이메일<input name="email" type="email" required maxlength="150" placeholder="teacher@example.com" autocomplete="off"></label><label class="form-field">관심 분야<select name="interest" required><option value="">선택해 주세요</option><option>SEM 기초 및 관찰</option><option>식물 미세구조</option><option>동물 미세구조</option><option>미생물 관찰</option><option>생물 수업 활용</option></select></label><label class="form-field">참여하고 싶은 활동<textarea name="message" maxlength="500" placeholder="함께 탐구하고 싶은 주제를 적어주세요."></textarea></label><button class="button primary wide" type="submit">승인 대기 화면 미리보기</button></form></div>`);return;}if(mode==='pending'){openModal(`<div class="modal-inner"><div class="status-seal" aria-hidden="true">✓</div><div class="eyebrow">MEMBERSHIP PREVIEW</div><h2 id="modal-title">운영진 승인 대기</h2><p>실제 가입 시 신청 정보를 확인한 뒤 승인 결과를 안내하는 화면입니다.</p><div class="auth-message"><strong>미리보기 상태</strong><br>실제 신청은 접수되지 않았으며 입력한 정보는 저장하지 않았습니다.</div><p class="preview-note">승인 전에는 회원 글쓰기와 자료 등록을 이용할 수 없습니다.</p><button class="button primary wide" data-close>둘러보기로 돌아가기</button></div>`);return;}openModal(`<div class="modal-inner"><div class="eyebrow">WELCOME TO BIOSEM</div><h2 id="modal-title">다시 만나서 반갑습니다.</h2><p>로그인하고 동료 선생님들의 발견을 만나보세요.</p><button class="social-button" disabled><b aria-hidden="true">G</b>구글로 계속하기<small>연결 예정</small></button><button class="social-button kakao" disabled><b aria-hidden="true">●</b>카카오로 계속하기<small>연결 예정</small></button><div class="auth-message">로그인 서비스는 준비 중입니다.<br>회원 활동은 로그인과 운영진 승인 후 이용할 수 있습니다.</div><div class="auth-switch">아직 회원이 아니신가요?<button data-auth="join">참여 안내</button></div></div>`);}
function openResource(id){const r=resources.find(x=>x.id===id);if(!r)return;openModal(`<article class="article-content"><div class="eyebrow">${r.type}</div><h2 id="modal-title">${r.title}</h2>${r.content}${id==='worksheet'?'<button class="button primary" data-print style="margin-top:25px">활동지 인쇄하기</button>':''}</article>`,'article-modal');}
function showActivity(id){const a=activities.find(x=>x.id===id);if(!a)return;openModal(`<article class="article-content"><div class="eyebrow">${a.category}</div><h2 id="modal-title">${a.title}</h2>${sample}<img class="article-image" src="assets/${a.image}" alt="활동 주제와 관련된 공개 SEM 이미지"><p class="article-caption">공개 관찰 이미지 · 실제 활동 사진이 아닙니다.</p><h3>활동 구성</h3><p>${a.body}</p><h3>함께 살펴볼 것</h3><ul>${a.points.map(p=>`<li>${p}</li>`).join('')}</ul><div class="auth-message">활동 기록의 구성을 보여주는 예시입니다. 실제 일정과 참여자, 활동 내용은 자료 확인 후 등록합니다.</div></article>`,'article-modal');}
function showPost(id){const p=posts.find(x=>x.id===id);if(!p)return;openModal(`<article class="article-content"><div class="eyebrow">${p.category}</div><h2 id="modal-title">${p.title}</h2>${p.body}</article>`,'article-modal');}
function render(){const [page='',detail]=location.hash.replace(/^#\/?/,'').split('/');const views={'':home,about,activities:activitiesPage,gallery:galleryPage,resources:resourcesPage,members:membersPage,community:communityPage,credits:creditsPage};if(modal.open)closeModal();main.innerHTML=(views[page]||home)();document.title=page&&navLabels[page]?`${navLabels[page]} | BioSEM`:'BioSEM — 작은 세계, 더 넓은 배움';document.querySelectorAll('nav a').forEach(a=>{const active=a.hash===`#/${page}`;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'instant'});if(detail&&page==='activities')showActivity(detail);if(detail&&page==='community')showPost(detail);}
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.auth)openAuth(el.dataset.auth);if(el.dataset.image)openImage(el.dataset.image);if(el.dataset.resource)openResource(el.dataset.resource);if(el.hasAttribute('data-close')||el.classList.contains('modal-close'))closeModal();if(el.classList.contains('menu-toggle')){const open=$('#navigation').classList.toggle('open');el.setAttribute('aria-expanded',String(open));el.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');}if(el.dataset.filter){const group=el.closest('[data-filter-group]');group.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});const type=group.dataset.filterGroup,value=el.dataset.filter;if(type==='gallery'){const list=images.filter(x=>value==='all'||x.category===value);$('#gallery-results').innerHTML=list.map(imageCard).join('');$('#gallery-count').textContent=`${list.length}개의 관찰 이미지`;}if(type==='activities'){const list=activities.filter(x=>value==='전체'||x.category===value);$('#activity-results').innerHTML=list.map(activityCard).join('');$('#activity-count').textContent=`${list.length}개의 예시 기록`;}if(type==='community'){$('#community-results').innerHTML=value==='공지사항'?postList():value==='활동 일정'?'<div class="empty-state"><div class="empty-symbol" aria-hidden="true">▦</div><h2>다음 만남을 준비하고 있습니다.</h2><p>정기 모임과 워크숍 일정은 확정 후 안내합니다.</p></div>':`<div class="empty-state"><div class="empty-symbol" aria-hidden="true">◎</div><h2>${value==='자유 나눔'?'선생님의 첫 이야기를 기다립니다.':'함께 탐구할 질문을 남겨주세요.'}</h2><p>승인된 회원이 경험과 질문을 나누는 공간입니다.<br>회원 인증 연결 후 이용할 수 있습니다.</p><button class="button primary" data-auth="join">참여 안내</button></div>`;}}if(el.hasAttribute('data-print'))printWorksheet();});
document.addEventListener('submit',event=>{if(event.target.id==='join-form'){event.preventDefault();event.target.reset();openAuth('pending');}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
modal.addEventListener('close',()=>{modal.dataset.revision=String(Number(modal.dataset.revision||0)+1);document.body.style.overflow='';});
function printWorksheet(){const r=resources.find(x=>x.id==='worksheet');const frame=document.createElement('iframe');frame.setAttribute('title','인쇄할 관찰 활동지');frame.style.cssText='position:fixed;width:0;height:0;border:0;';document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write(`<!doctype html><html lang="ko"><head><meta charset="UTF-8"><title>BioSEM 탐구 기록지</title><style>body{font-family:sans-serif;max-width:720px;margin:25px auto;font-size:14px;line-height:1.7}h1{font-size:23px}h3{font-size:17px;margin-top:22px}@page{size:A4;margin:18mm}</style></head><body><h1>BioSEM · 관찰 → 질문 → 설명</h1>${r.content}</body></html>`);doc.close();frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000);}
window.addEventListener('hashchange',render);render();

window.BioSEMUI={openModal,closeModal,openPreviewAuth,render};
